impl<const STORED_CURVE_COUNT: usize, const NUMBER_OF_POINTS: usize> WriteAdapter
    for Model710StatefulAdapter<STORED_CURVE_COUNT, NUMBER_OF_POINTS>
{
    /// DER Trip HF Module Enable (Ena)
    ///
    /// DER high frequency trip control enable.
    fn set_der_trip_hf_module_enable(&mut self, value: Ena) {
        self.der_trip_hf_module_enable = value;
    }

    /// Adopt Curve Request (AdptCrvReq)
    ///
    /// Index of curve points to adopt. First curve index is 1.
    fn set_adopt_curve_request(&mut self, value: u16) {
        self.adopt_curve_request = value;
    }

    /// Number Of Active Points (ActPt)
    ///
    /// Number of active points in must trip curve.
    fn set_must_trip_curve_crv_number_of_active_points(&mut self, value: u16, crv_index: u16) {
        self.stored_curves[crv_index as usize].must_trip_curve_crv_number_of_active_points = value;
    }

    /// Number Of Active Points (ActPt)
    ///
    /// Number of active points in may trip curve.
    fn set_may_trip_curve_crv_number_of_active_points(&mut self, value: u16, crv_index: u16) {
        self.stored_curves[crv_index as usize].may_trip_curve_crv_number_of_active_points = value;
    }

    /// Number Of Active Points (ActPt)
    ///
    /// Number of active points in the momentary cessation curve.
    fn set_momentary_cessation_curve_crv_number_of_active_points(
        &mut self,
        value: u16,
        crv_index: u16,
    ) {
        self.stored_curves[crv_index as usize]
            .momentary_cessation_curve_crv_number_of_active_points = value;
    }

    /// Frequency Point (Hz)
    ///
    /// Curve frequency point.
    ///
    /// Internal curve conformance checks should be conducted when AdptCrvReq is set to 1, not on point writes.
    fn set_must_trip_curve_pt_frequency_point(
        &mut self,
        value: u32,
        crv_index: u16,
        pt_index: u16,
    ) {
        self.stored_curves[crv_index as usize].must_trip_curve_must_trip_curve_points
            [pt_index as usize]
            .must_trip_curve_pt_frequency_point = value;
    }

    /// Time Point (Tms)
    ///
    /// Curve time point in seconds.
    ///
    /// Internal curve conformance checks should be conducted when AdptCrvReq is set to 1, not on point writes.
    fn set_must_trip_curve_pt_time_point(&mut self, value: u32, crv_index: u16, pt_index: u16) {
        self.stored_curves[crv_index as usize].must_trip_curve_must_trip_curve_points
            [pt_index as usize]
            .must_trip_curve_pt_time_point = value;
    }

    /// Frequency Point (Hz)
    ///
    /// Curve frequency point.
    fn set_may_trip_curve_pt_frequency_point(&mut self, value: u32, crv_index: u16, pt_index: u16) {
        self.stored_curves[crv_index as usize].may_trip_curve_may_trip_curve_points
            [pt_index as usize]
            .may_trip_curve_pt_frequency_point = value;
    }

    /// Time Point (Tms)
    ///
    /// Curve time point in seconds.
    fn set_may_trip_curve_pt_time_point(&mut self, value: u32, crv_index: u16, pt_index: u16) {
        self.stored_curves[crv_index as usize].may_trip_curve_may_trip_curve_points
            [pt_index as usize]
            .may_trip_curve_pt_time_point = value;
    }

    /// Frequency Point (Hz)
    ///
    /// Curve frequency point.
    fn set_momentary_cessation_curve_pt_frequency_point(
        &mut self,
        value: u32,
        crv_index: u16,
        pt_index: u16,
    ) {
        self.stored_curves[crv_index as usize]
            .momentary_cessation_curve_mom_cessation_curve_points[pt_index as usize]
            .momentary_cessation_curve_pt_frequency_point = value;
    }

    /// Time Point (Tms)
    ///
    /// Curve time point in seconds.
    fn set_momentary_cessation_curve_pt_time_point(
        &mut self,
        value: u32,
        crv_index: u16,
        pt_index: u16,
    ) {
        self.stored_curves[crv_index as usize]
            .momentary_cessation_curve_mom_cessation_curve_points[pt_index as usize]
            .momentary_cessation_curve_pt_time_point = value;
    }
}

/// C-FFI dispatch descriptor for SunSpec model 710. A C `SunspecModelBinding` points
/// at this static, so the service functions dispatch with no model-id lookup.
#[unsafe(no_mangle)]
pub static SUNSPEC_MODEL_710: StaticModelSpec = StaticModelSpec {
    id: 710,
    length: model_710_c_length,
    writable: true,
    visit_read: model_710_c_visit_read,
    visit_write: model_710_c_visit_write,
};

fn model_710_c_length(repeat_count_0: u16, repeat_count_1: u16) -> u16 {
    (Model710 {
        stored_curve_count: repeat_count_0,
        number_of_points: repeat_count_1,
    })
    .model_length()
}

/// # Safety
/// For `kind` 1 or 2, `adapter` must point to a live `Model710{Stateful,Callback}Adapter`,
/// valid for the duration of the call.
unsafe fn model_710_c_visit_read(
    kind: u8,
    adapter: *const c_void,
    repeat_count_0: u16,
    repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &mut WritableRegisterBuffer<'_>,
) {
    let model = Model710 {
        stored_curve_count: repeat_count_0,
        number_of_points: repeat_count_1,
    };
    let adapter: Option<&dyn ReadAdapter> = match kind {
        2 => Some(unsafe { &*(adapter as *const Model710CallbackAdapter) } as &dyn ReadAdapter),
        _ => None,
    };
    cursor.visit_source_block(model.model_length(), |offset, from, len| {
        let mut block = buffer.slice(from, len);
        match adapter {
            Some(adapter) => model.traverse_points_read(adapter, &mut block, offset),
            None => {
                block.fill(&[0xff, 0xff]);
                Ok(())
            }
        }
    });
}

/// # Safety
/// As for [`model_710_c_visit_read`], and `adapter` must be uniquely borrowable for the call.
unsafe fn model_710_c_visit_write(
    kind: u8,
    adapter: *mut c_void,
    repeat_count_0: u16,
    repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &ReadableRegisterBuffer<'_>,
) {
    let model = Model710 {
        stored_curve_count: repeat_count_0,
        number_of_points: repeat_count_1,
    };
    let adapter: Option<&mut dyn WriteAdapter> = match kind {
        2 => {
            Some(unsafe { &mut *(adapter as *mut Model710CallbackAdapter) } as &mut dyn WriteAdapter)
        }
        _ => None,
    };
    cursor.visit_source_block(model.model_length(), |offset, from, len| match adapter {
        Some(adapter) => model.traverse_points_write(adapter, &buffer.slice(from, len), offset),
        None => Err(ModbusException::IllegalDataAddress),
    });
}
